function TriggerGiftBag:AddListener()
    KTool.GetOrAddComponent(self.BtnClose.gameObject, typeof(UIEventProxy)).onPointerClick = function()
        self:OnCloseBtnClick()
    end

    SetButtonAction(self.BtnClose1,Bind(self,self.OnCloseBtnClick))
    SetButtonAction(self.BtnLeft, Bind(self, self.ActionBtnLeft))
    SetButtonAction(self.BtnRight, Bind(self, self.ActionBtnRight))
    self.eventGiftRefresh = Events.AddListener(Constants.EventNames.TriggerGiftRefresh, function()
        self:RefreshDialogInfo()
    end)
    self.EventSdkEvent = Events.AddListener(Constants.EventNames.EVENT_SDK, Bind(self, self.OnEventSdkEvent))
end

function TriggerGiftBag:OnCloseBtnClick()
    if self.isCache then
        self.compTriggerGift:RemoveLastCacheTriggerChest()
        local cacheData = self.compTriggerGift:GetCacheTriggerGift()
        if table.count(cacheData) > 0 then
            self:RefreshDialogInfo()
        else
            self:ClosePanel()
        end
    else
        self:ClosePanel()
    end
end

function TriggerGiftBag:ClosePanel()
    self:StopTimer()
    if self.isPopUp or self.isCache then
        CfUtils.StartCoroutineWithBlocker(function()
            xTry(function()
                CfUtils.PlayAnimation(self.RootAnimator,"TriggerGiftBagRoot_Out")
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(CfUtils.GetAnimationTime(self.RootAnimator,"TriggerGiftBagRoot_Out")))
                Events.Broadcast(Constants.EventNames.START_SHOW_BOOM_MOVE,Constants.UIHomeViewBtnType.BtnGiftBag)
                UIModule.CloseDialog(self.controller)
            end)
        end)
    else
        UIModule.CloseDialog(self.controller)
    end
end
function TriggerGiftBag:OnFocus(focus)
    if focus then
        ---@type ServerDifferenceMgr
        local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
        ServerDifferenceMgr:RefreshNavigatorGoods(true)
    end
end
function TriggerGiftBag:RemoveListener()
    if self.eventGiftRefresh then
        Events.RemoveListener(Constants.EventNames.TriggerGiftRefresh, self.eventGiftRefresh)
        self.eventGiftRefresh = nil
    end
    if self.EventSdkEvent then
        Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.EventSdkEvent)
        self.EventSdkEvent = nil
    end

end

