function TriggerGiftBag:GetAimPanel(refId)
    local go
    if not IsNull(self.Panel1) then
        go = KTool.Instantiate(self.Content.gameObject, self.Panel1.gameObject)
        KTool.SetActive(go, true)
    end
    return go
end
---@return TriggerGiftPanel
function TriggerGiftBag:InitSingleGiftPanel(data)
    local giftConfigData = data.configData
    local refId = giftConfigData.id
    local goPanel = self:GetAimPanel(refId)
    local panelEnv = CfUtils.GetLuaScr(goPanel, LUA_PATH_GIFT_PANEL)
    ---@type TriggerGiftRewardsVo
    local giftRewardData = CfUtils.GetCfVo(AutoIds.IdSetting2002, "TriggerGiftRewardsVo", refId)
    if not IsNull(panelEnv) then
        ---@type TriggerGiftPanel
        local rewards = clone(giftConfigData.rewards) 
        panelEnv:InitRewardsList(rewards)
        --- 购买按钮
        local goodNum = giftRewardData.goodsConsumNum[1]

        panelEnv:InitBtnBuy(giftConfigData.id, giftConfigData.expirationTime,  giftConfigData.price,giftRewardData.iconTitle, giftRewardData.rebate ,  function()
            local prices =  giftConfigData.prices or {}
            if table.count(prices) > 0 then
                local currrency = nil
                local price = nil
                for goodsId, v in pairs(prices) do
                    currrency =  checkInt(goodsId) 
                    price = v.current
                end
                print(GoodsUtils.GetThingNo(currrency))
                ---@type ServerDifferenceMgr
                local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
                ServerDifferenceMgr:WrapPrimaryCurrencyBuy({
                    currency = currrency,
                    current = price,
                }, function(isSuccess)
                    isSuccess = checkBool(isSuccess)
                    if not isSuccess then
                        return
                    end
                    ----请求兑换的逻辑
                    GameUtils.Request(Interfaces.OverseaMallTriggerChestProductBuy,{
                        productId  = giftConfigData.productId,
                        currency = currrency,
                        num = 1,
                    }, function(request,response)
                        if checkInt(response.errCode) == 0 then
                            local oneReawards = response.data.rewards  or {}
                            local rewards = clone(oneReawards)
                            rewards[#rewards+1] = {
                                goodsId = currrency ,
                                num = -price,
                                productId = giftConfigData.productId,
                            }
                            local rewards2 = clone(response.data.rewards)
                            GoodsUtils.DrawRewards(rewards)
                            if #oneReawards > 0 then
                                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards2, cb = function()
                                    if self.isCache then
                                        self.compTriggerGift:TriggerCacheGiftReq(true,function()
                                            --self:RefreshDialogInfo()
                                        end)
                                    else
                                        self.compTriggerGift:TriggerGiftReq(function()
                                            --self:RefreshDialogInfo()
                                        end)
                                    end
                                end  } })
                            else 
                                if self.isCache then
                                    self.compTriggerGift:TriggerCacheGiftReq(true,function()
                                        --self:RefreshDialogInfo()
                                    end)
                                else
                                    self.compTriggerGift:TriggerGiftReq(function()
                                        --self:RefreshDialogInfo()
                                    end)
                                end
                            end
                           
                        end
                    end )
                end)
            else    
                local productId = checkNumber(data.giftData.productId)
                local channelProductId = checkString(data.giftData.channelProductId)
                local SDKService = import('Game.Entry.SDKService')
                SDKService:GetInstance():PayMoney({
                    productId = productId,
                    channelProductId = channelProductId,
                    productDesc = localize("触发礼包"),
                    payAmount = data.giftData.dataConfig.price,
                    data = data.giftData
                })
            end
         
        end , data.giftData.channelProductId)

        KTool.SetActive(goPanel, false)
    end
    return panelEnv
end

function TriggerGiftBag:AddTimer(times)
    self:StopTimer()
    self.triggerTimer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count)
        if count > 0 then
            if self.listPanel then
                local currentTime = playerDojo:GetServerTime();
                for i, v in pairs(self.listPanel) do
                    local expirationTime = checkInt(v:getExpirationTime())
                    if expirationTime > 0 then
                        if expirationTime >= currentTime then
                            v:SetTimeDownValue(expirationTime -currentTime)
                        else
                            self:StopTimer()
                            self:RefreshDialogInfo()
                        end
                    end
                end
            end
        else
            self:StopTimer()
            self:RefreshDialogInfo()
        end
    end, times, false, true)
end

function TriggerGiftBag:StopTimer()
    if self.triggerTimer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.triggerTimer)
        self.triggerTimer = nil
    end
end

