function TriggerGiftBag:RefreshDialogInfo()
    local listGift = self:GetListGift()
    if isNull(listGift) or #listGift <= 0 then
        self:OnCloseBtnClick()
        return
    end

    self:CleanInitGO()
    self:InitGiftsList()
end

function TriggerGiftBag:GetListGift()
    local listGift = {}
    if self.isCache then
        listGift = self.compTriggerGift:GetLastCacheTriggerGift()
    else
        listGift = self.compTriggerGift:GetEffectTriggerGift()
    end
    return listGift
end

function TriggerGiftBag:CleanInitGO()
    if self.listDots then
        for i = #self.listDots, 1, -1 do
            KTool.SafeDelete(self.listDots[i].gameObject)
        end
        self.listDots = nil
    end
    if self.listPanel then
        for i = #self.listPanel, 1, -1 do
            KTool.SafeDelete(self.listPanel[i].controller.gameObject)
        end
        self.listPanel = nil
    end
end

function TriggerGiftBag:InitGiftsShow()
    xTry(function()
        local longTime  = self.compTriggerGift:GetLongestTimes()
        if longTime > 0 then
            self:StopTimer()
            self:AddTimer(longTime)
        end
        self.listGift = self:GetListGift()

        self:InitRootDots(#self.listGift)
        if #self.listGift > 0 then
            self.indexPanel = 1
            self:UpdateGiftPanel()
        end
        self:UpdatePanelChangeBtnShowState()

    end)
end

function TriggerGiftBag:InitGiftsList()
    xTry(function()
        local longTime  = self.compTriggerGift:GetLongestTimes()
        if longTime > 0 then
            self:StopTimer()
            self:AddTimer(longTime)
        end
        local listGift = self:GetListGift()

        self.listPanel = {}
        for i, vGift in pairs(listGift) do
            local panel = self:InitSingleGiftPanel(vGift)
            if panel then
                table.insert(self.listPanel, panel)
            end
        end
        self:InitRootDots(#listGift)
        if #listGift > 0 then
            self.indexPanel = 1
            self:UpdateGiftPanel()
        end
        self:UpdatePanelChangeBtnShowState()

    end)
end

function TriggerGiftBag:OnEventSdkEvent(parameters)
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        if self.isCache then
            self.compTriggerGift:TriggerCacheGiftReq(true,function()
                --self:RefreshDialogInfo()
            end)
        else
            self.compTriggerGift:TriggerGiftReq(function()
                --self:RefreshDialogInfo()
            end)
        end
    end
end

function TriggerGiftBag:InitRootDots(num)
    self.listDots = {}
    local countPage = num -- todo需要服务器数据
    local goDot = self.RootDots:Find("ImgDot").gameObject
    if not IsNull(goDot) then
        for i = 1, countPage do
            local go = KTool.Instantiate(self.RootDots.gameObject, goDot, false)
            if not IsNull(go) then
                KTool.SetActive(go, true)
                local siDotCell = KTool.GetOrAddComponent(go, typeof(CS.Game.Native.Common.UISwitchImage))
                if not IsNull(siDotCell) then
                    table.insert(self.listDots, siDotCell)
                end
            end
        end
    end
end

function TriggerGiftBag:UpdateGiftPanel(type)
    if self.indexPanel and self.indexPanel > 0 then
        if self.coPanelChange then
            cs_coroutine.stop(self.coPanelChange)
            self.coPanelChange = nil
        end
        local panelNow = self.listPanel[self.indexPanel]
        local panelEX = self.listPanel[self.indexPanelEX]
        if #self.listPanel > 1 and panelEX then
            self.coPanelChange = cs_coroutine.start(function()
                KTool.SetActive(panelNow.controller.gameObject, true)
                KTool.SetActive(panelEX.controller.gameObject, true)
                if type == Panel_Change_Type.Left then
                    panelEX:PlayAnimExitL()
                    panelNow:PlayAnimEntryL()
                else
                    panelEX:PlayAnimExitR()
                    panelNow:PlayAnimEntryR()
                end
                cs_coroutine.yield_return(CS.UnityEngine.WaitForSeconds(TIME_PANEL_CHANGE))
                self:RefreshSubPanel()
                self:UpdateListDots(self.indexPanel)
            end)
        else
            self:RefreshSubPanel()
            self:UpdateListDots(self.indexPanel)
            self:PlayEntryAni()
        end
    end
end

function TriggerGiftBag:PlayEntryAni()
    if not isNull(self.listPanel[self.indexPanel]) then
        self.listPanel[self.indexPanel]:PlayAnimEntry()
    end
end

function TriggerGiftBag:RefreshSubPanel()
    for i, panel in pairs(self.listPanel) do
        KTool.SetActive(panel.controller.gameObject, i == self.indexPanel)
    end
end

function TriggerGiftBag:UpdateListDots(index)
    for i, dot in pairs(self.listDots) do
        dot.Status = (index == i) and 1 or 2
        dot:Reset()
    end
end

function TriggerGiftBag:ActionBtnLeft()
    self.indexPanelEX = self.indexPanel
    self.indexPanel = self.indexPanel - 1 < 1 and #self.listPanel or self.indexPanel - 1
    self:UpdateGiftPanel(Panel_Change_Type.Left)
end

function TriggerGiftBag:ActionBtnRight()
    self.indexPanelEX = self.indexPanel
    self.indexPanel = self.indexPanel + 1 > #self.listPanel and 1 or self.indexPanel + 1
    self:UpdateGiftPanel(Panel_Change_Type.Right)
end

function TriggerGiftBag:UpdatePanelChangeBtnShowState()
    local count = isNull(self.listPanel) and 0 or #self.listPanel
    KTool.SetActive(self.BtnLeft.gameObject, count > 1)
    KTool.SetActive(self.BtnRight.gameObject, count > 1)
end

return TriggerGiftBag